"""The campus buildings' art: generated by an image model, then turned into pixel art.

Usage (from the repository root):

    uv run --with pillow python scripts/campus-buildings.py process
    OPENROUTER_API_KEY=... python scripts/campus-buildings.py generate [name ...]

`generate` asks the image model for one building per prompt below and writes the raw
1024px image to assets/campus-buildings/raw/. It costs money and is not deterministic, so
it only runs by hand, for the buildings named (all of them when none is). The raw images
are committed: they are the source, like a vendor drop.

`process` is deterministic and needs no network: it keys out the magenta background,
trims and reduces the image to the characters' own pixel density (ADR 0075) — one art
pixel per game pixel, the campus being drawn like the interiors and shown at 2x — with a
limited palette and hard alpha. scripts/render-campus-pixel-art.py places the results.
"""
from pathlib import Path
import base64
import json
import os
import sys
import urllib.request

ROOT = Path(__file__).resolve().parent.parent
RAW = ROOT / 'assets' / 'campus-buildings' / 'raw'
OUT = ROOT / 'assets' / 'campus-buildings'
# The current fantasy stamp: only a reference for camera angle and framing.
REFERENCE = ROOT / 'assets' / 'graphics' / 'graphics' / 'objects' / 'house_large.png'
MODEL = 'openai/gpt-5.4-image-2'
# The box each building is fitted into, in game pixels (width, height). The player is 32
# pixels tall: a two-story facade plus its roof is several times that.
SIZES = {
    'biblioteca': (232, 232),
    'centro-de-convivencia': (184, 184),
    'auditorio': (232, 232),
    'centro-esportivo': (208, 208),
    'bloco-de-tecnologia': (216, 216),
    'portao': (28, 56),
    'portaria': (176, 144),
}

BASE = (
    'Pixel art game asset for a top-down 2D RPG. Use the attached image ONLY as a reference '
    'for camera angle, framing and pixel-art style: the building is seen straight from the '
    'front, the roof is seen from above and fills the upper part, the facade faces the '
    'viewer, no perspective, no isometric angle, crisp hard pixels with a dark outline, '
    'limited palette, soft daylight from the top-left. {what} The building fills the whole '
    'canvas edge to edge, like the reference. The background must be a single flat solid '
    'pure magenta color (#FF00FF) everywhere outside the building, with no shadow on it. '
    'No text, no letters, no signs, no logos, no people, no cars, no ground.'
)
ROOF = (
    'The roof is not a plain slab: it has visible details such as air-conditioning units, '
    'skylights, vents or a water tank.'
)
PROMPTS = {
    'biblioteca': 'Draw the LIBRARY of a modern Brazilian university campus in Fortaleza: a '
    'wide, low two-story modernist building in white and light-grey exposed concrete, a row '
    'of vertical concrete sun-breaker fins (brise-soleil) over large blue-tinted glass '
    'windows on the upper floor, a wide glass entrance in the middle under a concrete '
    'canopy, small palms and tropical plants at the base. ' + ROOF + ' Square image.',
    'centro-de-convivencia': 'Draw the STUDENT LIVING CENTER (centro de convivencia) of a '
    'Brazilian university in Fortaleza: an open one-story tropical pavilion with a large '
    'overhanging roof of terracotta-red clay tiles supported by round white concrete '
    'columns, open sides showing a few cafe tables and benches inside the shade, a small '
    'snack counter with a striped awning, potted plants. Square image.',
    'auditorio': 'Draw the AUDITORIUM of a Brazilian university in Fortaleza: a solid '
    'modernist block in raw grey concrete with a curved, fan-shaped roof seen from above, a '
    'tall entrance of glass doors with a wide concrete marquee, two vertical decorative '
    'concrete panels with a geometric relief on each side, a few steps up to the entrance, '
    'small shrubs. Square image.',
    'centro-esportivo': 'Draw the SPORTS CENTER (gymnasium) of a Brazilian university in '
    'Fortaleza: a one-story gym hall with a shallow arched metal roof in blue-grey '
    'corrugated steel seen from above, white walls with a high band of horizontal '
    'ventilation louvers, a wide open entrance, a green accent stripe along the wall, a '
    'small basketball hoop silhouette visible through the entrance. Square image.',
    'bloco-de-tecnologia': 'Draw the TECHNOLOGY BLOCK of a Brazilian university in '
    'Fortaleza: a sleek modern two-story building with a dark blue-glass curtain wall in a '
    'grid of panes, white aluminum frames, one side clad in dark grey metal panels, a slim '
    'glass entrance, a row of small server ventilation grilles near the base, a rooftop '
    'with solar panels and antennas. ' + ROOF + ' Square image.',
    'portaria': 'Draw the GATEHOUSE (portaria) at the main entrance of a modern Brazilian '
    'university campus in Fortaleza: a small one-story security booth in white concrete with '
    'a wide flat cantilevered roof slab seen from above, a long glass window with a counter, '
    'a glass door on the front, a few wall screens visible through the glass, a low planter '
    'with tropical plants along the front. Wider than tall. Landscape image, about 5:4.',
    'portao': 'Draw ONE GATE PILLAR of the main entrance of a modern Brazilian university '
    'campus: a tall narrow rectangular pillar in white concrete with a dark grey stone base, '
    'a thin horizontal metal band near the top and a small light fixture on top. The pillar '
    'is twice as tall as it is wide and fills a tall portrait canvas. Portrait image, height '
    'twice the width.',
}


def generate(names):
    key = os.environ.get('OPENROUTER_API_KEY')
    if not key:
        raise SystemExit('OPENROUTER_API_KEY is not set')
    reference = 'data:image/png;base64,' + base64.b64encode(REFERENCE.read_bytes()).decode()
    RAW.mkdir(parents=True, exist_ok=True)
    for name in names:
        body = {
            'model': MODEL,
            'modalities': ['image', 'text'],
            'messages': [{'role': 'user', 'content': [
                {'type': 'text', 'text': BASE.format(what=PROMPTS[name])},
                {'type': 'image_url', 'image_url': {'url': reference}},
            ]}],
        }
        request = urllib.request.Request(
            'https://openrouter.ai/api/v1/chat/completions',
            json.dumps(body).encode(),
            {'Authorization': f'Bearer {key}', 'Content-Type': 'application/json'},
        )
        response = json.load(urllib.request.urlopen(request, timeout=600))
        images = response['choices'][0]['message'].get('images') or []
        if not images:
            raise SystemExit(f'{name}: the model returned no image')
        url = images[0]['image_url']['url']
        (RAW / f'{name}.png').write_bytes(base64.b64decode(url.split(',', 1)[1]))
        print(f'generated {name}')


def is_background(r, g, b):
    # Pure magenta and the pinkish fringe the model blends into it.
    return r > 150 and b > 150 and g < 110 and abs(r - b) < 90


def process(names):
    from PIL import Image

    for name in names:
        image = Image.open(RAW / f'{name}.png').convert('RGBA')
        pixels = image.load()
        width, height = image.size
        for y in range(height):
            for x in range(width):
                r, g, b, _ = pixels[x, y]
                if is_background(r, g, b):
                    pixels[x, y] = (0, 0, 0, 0)
        bbox = image.getbbox()
        if bbox is None:
            raise SystemExit(f'{name}: nothing left after keying')
        image = image.crop(bbox)

        box_w, box_h = SIZES[name]
        # Fit inside the box keeping proportions; the sprite is exactly the building.
        scale = min(box_w / image.width, box_h / image.height)
        fit_w = max(1, round(image.width * scale))
        fit_h = max(1, round(image.height * scale))
        canvas = image.resize((fit_w, fit_h), Image.Resampling.BOX)

        # Hard alpha and a limited palette: pixel art has no half-transparent edges.
        alpha = canvas.getchannel('A').point(lambda a: 255 if a >= 128 else 0)
        rgb = canvas.convert('RGB').quantize(colors=32, method=Image.Quantize.MEDIANCUT,
                                             dither=Image.Dither.NONE).convert('RGB')
        result = rgb.convert('RGBA')
        result.putalpha(alpha)
        result.save(OUT / f'{name}.png', optimize=True)
        print(f'processed {name} ({fit_w}x{fit_h})')


if __name__ == '__main__':
    if len(sys.argv) < 2 or sys.argv[1] not in ('generate', 'process'):
        raise SystemExit(__doc__)
    chosen = sys.argv[2:] or list(SIZES)
    unknown = [name for name in chosen if name not in SIZES]
    if unknown:
        raise SystemExit(f'unknown building: {", ".join(unknown)}')
    (generate if sys.argv[1] == 'generate' else process)(chosen)
